   * refetch path — callers never hand-roll list mutation.
   */
  cancelSubscriptions(params: {
    agentId: string;
    workspaceId: string;
    subscriptionId?: string;
    groupId?: string;
  }): Promise<MutationResult>;
  /**
   * Dismiss the pending Agent Q&A question set (`agent.dismissQuestions`,
